 "content": "def transform(grid):
    # The grid is a set of cells bounded by separator lines. Output the corner marker
    # value that is repeated at both ends of each separator direction.
    h, w = len(grid), len(grid[0])
    color_counts = {}
    for row in grid:
        for v in row:
            color_counts[v] = color_counts.get(v, 0) + 1
    sep = max(color_counts, key=color_counts.get)
    rows = [r for r in range(h) if sum(v == sep for v in grid[r]) >= w * 0.8]
    cols = [c for c in range(w) if sum(grid[r][c] == sep for r in range(h)) >= h * 0.8]
    marker_counts = {}
    for r in rows:
        for c in cols:
            v = grid[r][c]
            if v != sep:
                marker_counts[v] = marker_counts.get(v, 0) + 1
    return [[max(marker_counts, key=marker_counts.get)]]
